"""Snapping span times to a fixed step for payroll."""

from typing import List

from hourglass.parsing import format_span
from hourglass.models import Span

def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (2 * minute + step) // (2 * step) * step

def _snap_span(span: Span, step: int) -> Span:
    return Span(
        _snap(span.start, step),
        _snap(span.end, step)
    )

# ---
def label_spans(spans: List[Span], step: int) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), times snapped to step."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")
    labels = []
    for span in spans:
        snap = _snap_span(span, step)
        hours, rest = divmod(snap.minutes, 60)
        labels.append(f"{format_span(snap)} ({hours}h {rest}m)")
    return labels

