import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import label_spans

class LabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [parse_span("08:58-17:14")]
        self.assertEqual(
            label_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        spans = [parse_span("09:05-10:25")]
        self.assertEqual(
            label_spans(spans, 10),
            ["09:10-10:30 (1h 20m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(540, 600), Span(660, 720)]
        self.assertEqual(len(label_spans(spans, 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                label_spans([Span(0, 60)], step)

if __name__ == "__main__":
    unittest.main()
